print(type(d))
def walk(o, p='', depth=0):
    if depth>3: return
    if isinstance(o,dict):
        for k,v in list(o.items())[:12]:
            print(p+k, type(v).__name__, (len(v) if hasattr(v,'__len__') and not isinstance(v,str) else (v if not isinstance(v,(list,dict)) else '')))
            if isinstance(v,(dict,list)): walk(v,p+k+'.',depth+1)
    elif isinstance(o,list):
        print(p+'[len]',len(o))
        if o: walk(o[0],p+'[0].',depth+1)
walk(d)
PY

